import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";

const source = resolve(process.env.ONECAL_CONFIG ?? "config/calendars.json");
const target = resolve("src/generated/config.ts");
const parsed = JSON.parse(readFileSync(source, "utf8"));

mkdirSync(dirname(target), { recursive: true });
writeFileSync(
  target,
  "// Generated by scripts/generate-config.mjs — do not edit.\n" +
    `// Source: ${source}\n` +
    `export const embeddedConfig: unknown = ${JSON.stringify(parsed, null, 2)};\n`,
);

console.log(`[onecal] embedded ${source} -> ${target}`);
